def T(v):
    if isinstance(v, dict): return ", ".join(f"{k}: {T(x)}" for k, x in v.items() if x not in (None, ""))
    if isinstance(v, list): return "; ".join(T(x) for x in v)
    return str(v if v is not None else "")
def ct(m):
    c = m.get("contacts") or {}
    s = " · ".join(x for x in [T(c.get("email")), T(c.get("phone")), T(c.get("site"))] if x and "не подтвержд" not in x and x != "None")
    return s[:120] or "контакты — через сайт / saby.ru"

