# ── DOCX ──
import re
strip = lambda s: re.sub(r"<[^>]+>", "", str(s))
doc = docx.Document(); sec = doc.sections[0]; sec.orientation = WD_ORIENT.LANDSCAPE; sec.page_width, sec.page_height = sec.page_height, sec.page_width
for m in ("left_margin", "right_margin", "top_margin", "bottom_margin"): setattr(sec, m, Cm(1.5))
doc.styles["Normal"].font.name = "Calibri"; doc.styles["Normal"].font.size = Pt(10)
for t, x in B:
    if t == "h1": doc.add_heading(strip(x), 0)
    elif t == "h2": doc.add_heading(strip(x), 1)
    elif t in ("p", "box"): doc.add_paragraph(strip(x))
    elif t == "ul":
        for i in x: doc.add_paragraph(strip(i), style="List Bullet")
    elif t == "tb":
        tb = doc.add_table(rows=1, cols=len(x[0])); tb.style = "Light Grid Accent 1"
        for i, c in enumerate(x[0]): tb.rows[0].cells[i].text = strip(c)
        for r in x[1]:
            cells = tb.add_row().cells
            for i, c in enumerate(r): cells[i].text = strip(c)
        doc.add_paragraph()
doc.save("../STRATEGIYA_DOROZHNAYA_KARTA.docx")
